/* Incident and interview practice. All grading is rules-based or explicitly self-assessed. */
(function () {
  'use strict';
  const esc = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const choice = (text, score, feedback, consequence) => ({text, score, feedback, consequence});
  const step = (title, prompt, choices) => ({title, prompt, choices});
  const incidents = [
    {id:'dark-port', icon:'01', title:'The dark port', area:'Layer 1 → Layer 3', duration:'4 decisions', intro:'A newly installed server powers on, but its production NIC has no link. Handoff is due in 40 minutes. A technician suggests changing the VLAN immediately.', steps:[
      step('Take control','What is your first direction?',[
        choice('Confirm safe access, affected scope, expected port mapping, and recent changes.',2,'Establish the boundary and approved baseline before touching equipment. One device and one affected service require a different response than a rack-wide incident.','The team confirms one new server is affected; existing production traffic is stable.'),
        choice('Ask the network owner to change the VLAN first.',0,'A VLAN mismatch does not normally explain the absence of physical link. Unapproved configuration changes add risk and erase the baseline.','The network owner declines an unapproved change. The physical fault remains and the handoff clock is running.'),
        choice('Check the cable without confirming which device or port is affected.',1,'A physical check is appropriate, but identification and scope come first to prevent disturbing a healthy production connection.','The technician pauses at two similar ports. You now need to verify labels before proceeding.')]),
      step('Inspect the path','The verified server port still has no physical link. Which check best isolates the issue?',[
        choice('Verify link LEDs, seating, labels, cable condition, and optic type against the approved design.',2,'Work through Layer 1 systematically. For fiber, follow site laser-safety rules and use approved inspection and cleaning equipment.','Inspection finds the installed transceiver does not match the link design.'),
        choice('Swap the NIC, optic, cable, and switch port together.',0,'Changing several variables destroys fault isolation and expands the change scope. A recovery without a known cause is weak evidence.','Several identifiers now differ from the build record. The original cause is obscured.'),
        choice('Restart the server and hope autonegotiation recovers.',1,'A restart can be a controlled diagnostic step, but it is disruptive and premature before basic checks.','The restart provides no useful isolation. The team still needs to compare the physical path with the design.')]),
      step('Make a controlled correction','How do you authorize the next move?',[
        choice('Use the approved process to change one suspected component, record its identity, then verify expected speed and VLAN with the network owner.',2,'One change at a time preserves evidence. The service owner validates configuration; delivery staff do not improvise production settings.','A compatible optic restores link at the expected speed. The network owner confirms the assigned VLAN and addressing.'),
        choice('Move to any spare live switch port and update labels later.',0,'A spare-looking port may serve another tenant or network. Port selection must follow the approved design and change controls.','The unplanned port exposes a mapping and segmentation risk. Stop and restore the approved path before testing.'),
        choice('Escalate with only “network is down.”',1,'Escalating is reasonable when authority or expertise is needed, but include scope, timestamps, mapping, symptoms, tests, and changes.','The network owner asks for missing evidence before they can safely act.')]),
      step('Close with evidence','Link is now up. Is the server ready to hand over?',[
        choice('Validate the agreed end-to-end service checks, confirm healthy redundancy, attach test evidence, reconcile labels, and communicate acceptance.',2,'Link-up is only one layer. Handoff requires the agreed acceptance criteria, accurate records, and named ownership.','The receiving owner accepts the server with test evidence and a recorded prevention action for optic staging.'),
        choice('Close the ticket because the link LED is green.',0,'A green LED does not prove VLAN, IP routing, application reachability, or resilience.','An untested service issue could reach the customer; acceptance remains incomplete.'),
        choice('Ping the gateway and tell the technician to remember the fix.',1,'A gateway test is useful, but service validation and durable documentation are still required.','The local network works. End-to-end acceptance and the build record are still outstanding.')])]},
    {id:'rack-blast-radius', icon:'02', title:'One rack, many alarms', area:'Incident coordination', duration:'4 decisions', intro:'Eight servers in one rack lose connectivity within the same minute. Adjacent racks look normal. A cable installation finished ten minutes earlier.', steps:[
      step('Recognize shared dependencies','How do you organize the initial response?',[
        choice('Declare and scope the incident, pause related work, assign an incident lead, and check shared uplinks, switch health, and power.',2,'Simultaneous failures suggest a shared dependency. Establish coordination while protecting evidence and unaffected service.','The team confirms the rack uplink is down; server power is stable.'),
        choice('Have eight technicians independently reboot the eight servers.',0,'Independent changes can amplify an outage. The shared timing points first to common infrastructure.','Reboots add customer impact and noise without resolving the shared uplink.'),
        choice('Check a single server NIC while everyone else waits.',1,'A representative endpoint check can help, but ignoring common dependencies delays incident response.','The endpoint check confirms no upstream connectivity. The rack uplink now needs attention.')]),
      step('Preserve the baseline','A recently worked cable tray is close to the affected uplink. What next?',[
        choice('Record alarms and timestamps; compare port mappings and recent work with the approved MOP before physical inspection.',2,'Preserve the sequence of events and verify exactly what may be handled. Correlation is a lead, not proof of cause.','The work record identifies a displaced uplink patch lead next to the new installation.'),
        choice('Reseat every cable in the tray until alarms stop.',0,'Blind reseating expands the blast radius and destroys the ability to identify the failed path.','A healthy redundant path is put at risk; the incident lead must halt the uncontrolled work.'),
        choice('Assume the vendor caused it and demand a replacement switch.',0,'Assigning blame before collecting evidence damages coordination and may lead to unnecessary replacement.','The team loses time while the simple physical path remains unverified.')]),
      step('Recover deliberately','A qualified technician identifies the affected patch lead. What instruction do you give?',[
        choice('Confirm the approved repair and rollback with the incident and network owners, then correct only the identified path.',2,'Authorized, narrow recovery reduces risk. Confirm the path and protect any surviving redundancy before handling cables.','The uplink recovers and rack traffic returns without touching adjacent circuits.'),
        choice('Force traffic across the backup by disabling the remaining links.',0,'Manipulating remaining service paths without verified topology may convert degradation into a larger outage.','The proposed action risks the remaining service path; recovery needs explicit network-owner direction.'),
        choice('Wait for the next routine maintenance window without checking impact.',1,'A maintenance window is not the only authorized path; an active incident may use the documented emergency-change process.','The outage persists while the incident owner determines whether emergency repair is appropriate.')]),
      step('Prove and learn','Traffic is flowing again. What closes the incident responsibly?',[
        choice('Validate all affected services and redundancy, monitor stability, publish impact and timeline, and assign evidence-based prevention actions.',2,'Recovery, communication, and problem follow-up are distinct responsibilities. Prevent recurrence without blaming an individual.','All eight servers pass agreed checks; cable protection and work-area verification receive owners and due dates.'),
        choice('Stop once the alarm dashboard clears.',0,'Alarm clearance is insufficient proof of customer recovery or redundancy.','The team lacks evidence that every affected service recovered.'),
        choice('Send “fixed” to the stakeholder channel and archive the work order.',1,'Timely communication is good, but include scope, validation, remaining risk, and next actions.','Stakeholders know recovery occurred, but impact and prevention are not yet documented.')])]},
    {id:'fiber-flaps', icon:'03', title:'The intermittent fiber', area:'Optics & test evidence', duration:'4 decisions', intro:'A newly installed fiber link repeatedly drops. Optical receive levels fluctuate. The installation contractor says the cable passed yesterday.', steps:[
      step('Set safe boundaries','Which first response fits this fault?',[
        choice('Confirm impact, redundancy, recent changes, and authorized test scope; use trained staff and approved fiber-safety practices.',2,'Never look into a fiber end. Protect production and define isolation before disconnecting or testing an optical path.','The network owner authorizes testing the affected path while verified redundancy carries traffic.'),
        choice('Look into the connector to check whether light is coming through.',0,'Laser radiation may be invisible. Direct viewing is unsafe; use approved inspection and measurement equipment.','Work must stop immediately for the unsafe proposal and a qualified technician must establish the safe method.'),
        choice('Request yesterday’s test report and do nothing else.',1,'Historical evidence is useful, but it does not establish current safety, service impact, or circuit identity.','The old report arrives, but the affected circuit and current condition still require verification.')]),
      step('Inspect before replacing','How do you investigate the physical link?',[
        choice('Verify optic/fiber compatibility, connector condition, polarity, strain, and bend radius; inspect-clean-inspect with an approved process.',2,'Contamination and mechanical stress can affect loss. Match optics, wavelength, speed, reach, and fiber design; observe product specifications.','A tight bend and a contaminated connection are found on the mapped circuit.'),
        choice('Wipe the connector on a shirt and reconnect it.',0,'Improvised cleaning can add contamination or damage the end face. Use the approved cleaning and inspection process.','The end face may now require additional approved cleaning or replacement.'),
        choice('Install a higher-power optic regardless of the design.',0,'An incompatible optic can violate the optical budget or equipment specifications. More power is not a diagnosis.','The proposed substitution is rejected pending a design and optical-budget review.')]),
      step('Measure the fault','Which test approach gives the strongest evidence?',[
        choice('Use the required loss/power tests against the link budget; use OTDR when appropriate to locate events, with correct setup and isolation.',2,'A power meter measures received power; a calibrated source and meter measure loss. OTDR helps locate events and does not replace all acceptance tests.','Approved measurements identify excess loss at the suspect connection; correction brings results within specification.'),
        choice('Use an OTDR result as proof that every end-to-end requirement passes.',1,'OTDR is valuable, but setup, dead zones, launch/receive fibers, and required loss tests matter. Follow the acceptance plan.','The event trace helps localization. Required loss and service validation remain outstanding.'),
        choice('Declare success because the visual fault locator light reaches the far end.',0,'A VFL helps with continuity and some visible faults; it does not certify optical loss, bandwidth, or service stability.','Continuity is known, but the intermittent performance is not explained or accepted.')]),
      step('Accept a stable link','After the repair, how do you complete the work?',[
        choice('Confirm loss and power limits, monitor errors and flaps for the agreed period, validate services, and save results with port and cable IDs.',2,'Tie each measurement to the actual installed path and validate stable service before handoff.','The receiving owner gets traceable results, stable error counters, and corrected routing documentation.'),
        choice('Close immediately after a five-second link-up.',0,'A brief link-up does not demonstrate stability or acceptable optical margin.','The acceptance record cannot show that the intermittent fault has been resolved.'),
        choice('Store an unlabeled screenshot of receive power.',1,'A measurement needs circuit identity, timestamp, limits, method, and relevant service evidence.','A useful reading exists, but its traceability and acceptance context are missing.')])]},
    {id:'power-redundancy', icon:'04', title:'Two cords, one risk', area:'Facilities & redundancy', duration:'4 decisions', intro:'A rack is almost ready for handoff. Both power cords on several dual-supply servers appear to feed the same PDU. Facilities is working nearby.', steps:[
      step('Pause the right work','What should you do first?',[
        choice('Pause affected handoff, confirm the approved A/B design, scope impacted equipment, and engage the facilities and service owners.',2,'Two cords do not prove independent power paths. Delivery staff must respect electrical-work boundaries and the approved design.','The team confirms a wiring discrepancy affecting four dual-supply servers.'),
        choice('Pull a power cord to see whether the servers stay up.',0,'An improvised failure test can create an outage and expose hazards. Testing requires authorization and an agreed method.','The unapproved test is halted before the service owner can assess its impact.'),
        choice('Accept the rack because all servers currently power on.',0,'Present operation does not demonstrate required redundancy. Acceptance would knowingly pass a design discrepancy.','A single PDU failure could take down both supplies on the affected servers.')]),
      step('Understand the electrical boundary','How do you verify the intended arrangement?',[
        choice('Have authorized personnel trace the documented feeds, confirm capacity and circuit labels, and assess protection and work controls.',2,'Qualified facilities personnel own electrical assessment and any required isolation/lockout. The manager coordinates scope and evidence.','Facilities confirms the correct B-side outlets and available capacity under the approved design.'),
        choice('Open the PDU to trace its internal wiring yourself.',0,'Do not perform electrical work beyond your authorization and training. Follow site procedures and qualified-person requirements.','The unsafe action must stop; facilities establishes the proper electrical-work boundary.'),
        choice('Trust the A/B stickers without tracing them to the approved records.',1,'Labels are helpful, but this discrepancy demands verification against the actual design and facilities records.','The labels look plausible but do not yet prove feed independence or usable capacity.')]),
      step('Correct the discrepancy','What recovery plan should you approve?',[
        choice('Use a reviewed MOP with owners, impact controls, peer checks, and rollback; authorized staff correct one approved connection at a time.',2,'Power changes require deliberate coordination with the service and facilities owners. Preserve the known-good supply while following the MOP.','The approved connection changes restore the designed A/B arrangement with recorded peer checks.'),
        choice('Move all cords at once so the interruption is brief.',0,'Simultaneous changes can remove both power paths and prevent safe isolation. A short outage is still an outage.','The proposed shortcut threatens service; the change needs a safe reviewed sequence.'),
        choice('Tell the next shift to fix it when they have time.',1,'Deferral needs a named owner, risk acceptance, due date, and blocked handoff or explicit exception.','The discrepancy remains open; the next shift cannot treat the rack as accepted.')]),
      step('Validate redundancy','What evidence is required before acceptance?',[
        choice('Reconcile cable and circuit records, verify health and loading, execute only approved resilience tests, and obtain receiving-owner acceptance.',2,'Redundancy acceptance must use the approved test plan. Do not invent live power-failure tests.','The rack meets the agreed electrical and service acceptance criteria with traceable records.'),
        choice('Pull the upstream breaker without warning to prove failover.',0,'Unannounced electrical interruption is dangerous and can affect equipment beyond the rack.','The test proposal is rejected; only authorized and coordinated testing can proceed.'),
        choice('Photograph the new cord arrangement and call it complete.',1,'Photos help show routing, but they cannot establish circuit capacity, feed independence, or agreed acceptance.','The physical record improves, while facilities and service validation remain incomplete.')])]},
    {id:'change-outage', icon:'05', title:'The change went red', area:'Change & rollback', duration:'4 decisions', intro:'During an approved network migration, monitoring reports production impact. The MOP has rollback triggers and a 15-minute recovery checkpoint.', steps:[
      step('Stop expansion','What are your immediate priorities?',[
        choice('Stop additional change steps, check safety and impact, activate incident coordination, and preserve the timeline and current state.',2,'Stabilize first. A single coordinated response prevents additional unrelated actions while the team assesses the rollback criteria.','The incident lead confirms customer impact and freezes unrelated changes.'),
        choice('Continue the migration because the next step might fix everything.',0,'Proceeding through a rollback trigger without assessment can increase the blast radius and consume the recovery window.','Impact expands while the remaining rollback window shrinks.'),
        choice('Investigate privately before telling anyone.',0,'Delaying incident communication prevents the right owners from controlling risk and coordinating recovery.','Service owners lose valuable response time and do not have a shared incident picture.')]),
      step('Use the decision gate','The documented rollback trigger is met. The technician wants five more minutes to improvise a fix.',[
        choice('Use the approved rollback criteria with the change and incident owners; execute the tested rollback within the recovery window.',2,'A usable rollback has a trigger, owner, executable steps, time estimate, and verification. Follow the approved decision authority.','The owners initiate rollback while the known recovery path remains available.'),
        choice('Ignore the trigger because the technician is confident.',0,'Confidence is not evidence. Changing the decision rule during an incident introduces unmanaged risk.','The untested fix consumes recovery time and leaves the team without a controlled baseline.'),
        choice('Wait for an unrelated weekly approval meeting.',1,'Use the documented incident and emergency-change authority; an active outage cannot wait for a routine governance cycle.','The incident lead escalates through the correct emergency decision path.')]),
      step('Communicate clearly','Which stakeholder update is most useful?',[
        choice('State impact, current recovery action, named lead, known risks, and the next update time; separate facts from estimates.',2,'Concise factual updates create a shared picture. Do not promise a restoration time without evidence.','Stakeholders know what is affected, who owns recovery, and when they will hear more.'),
        choice('Promise everything will be fixed in two minutes.',0,'Unsupported certainty undermines trust and can cause stakeholders to make incorrect downstream decisions.','The arbitrary promise creates confusion when validation takes longer.'),
        choice('Send all raw logs with no impact summary.',1,'Logs support responders, but stakeholders need a clear impact and action summary tailored to their role.','Technical evidence is available, but decision-makers cannot readily understand the service risk.')]),
      step('Recover before analyzing','The rollback completes. What next?',[
        choice('Verify customer service and baseline configuration, monitor stability, document the incident, then investigate cause and improve the change controls.',2,'Restoration comes before the full problem investigation. A blameless review needs evidence, contributing factors, and owned actions.','The baseline is restored and accepted; a later review improves the prechecks and staged validation.'),
        choice('Repeat the failed migration immediately before the window closes.',0,'Reattempting without understanding the failure repeats the risk. A new attempt needs review and authorization.','A second attempt would jeopardize the recovered service and requires a new decision.'),
        choice('Blame the executing technician and close the incident.',0,'Individual blame does not establish root cause or address system weaknesses. Recovery still requires verification.','The organization loses the evidence and learning needed to prevent recurrence.')])]},
    {id:'vendor-recovery', icon:'06', title:'“Ninety percent complete”', area:'Vendors & delivery', duration:'4 decisions', intro:'A contractor reports 90% completion on a 20-rack deployment. A site walk shows missing labels, untested fibers, and only 11 racks ready for acceptance.', steps:[
      step('Establish real completion','How do you respond to the status mismatch?',[
        choice('Compare physical work and test evidence with agreed acceptance criteria; reconcile the status with the vendor using a joint walkdown.',2,'Define done through accepted deliverables, not effort or estimates. Use facts to align the recovery discussion.','The joint review confirms 11 accepted racks and a clear list of unfinished dependencies.'),
        choice('Report 90% upward because that is the vendor’s official number.',0,'Repeating unverified status hides delivery risk and prevents timely decisions.','Leadership receives a forecast that does not reflect usable capacity.'),
        choice('Reject every completed rack to pressure the vendor.',0,'Indiscriminate rejection ignores objective acceptance evidence and erodes accountability.','The team loses a reliable baseline for both accepted work and remaining work.')]),
      step('Find the constraint','What should the recovery plan investigate first?',[
        choice('Map remaining dependencies and critical path: materials, test capacity, skilled labor, approvals, and rework.',2,'Recovery targets the actual bottleneck. Adding people to blocked work may not improve accepted throughput.','Testing capacity and a missing optic shipment are identified as the critical constraints.'),
        choice('Add overtime to every crew without checking dependencies.',1,'Overtime may help some constraints, but indiscriminate overtime can add fatigue and cost without moving the critical path.','Crews wait on the same missing materials and testing resources while fatigue grows.'),
        choice('Skip fiber certification and finish the labels after handoff.',0,'Removing acceptance gates creates hidden defects. Recover time by resequencing ready work and fixing constraints.','The proposed shortcut would deliver unverified capacity and future rework.')]),
      step('Own the recovery','Which vendor agreement is strongest?',[
        choice('Set measurable milestones, named owners, material dates, quality gates, staffing safeguards, and an escalation cadence.',2,'A recovery plan needs verifiable outputs and decision dates. One accountable channel prevents conflicting directions.','The vendor commits to daily accepted-rack targets, a test crew, and a dated materials resolution.'),
        choice('Accept “we will try harder” as the recovery plan.',0,'Intent is not an executable commitment. Missing owners and dates make progress impossible to govern.','The next status report is still optimistic but cannot be checked against commitments.'),
        choice('Send separate directions from every internal team directly to the crew.',0,'Conflicting instructions create scope churn and errors. Coordinate priorities through the designated owner.','The vendor pauses to resolve contradictory instructions, further delaying progress.')]),
      step('Forecast honestly','What do you tell leadership?',[
        choice('Report accepted capacity, critical-path risk, a range supported by evidence, decisions needed, and the next review; track quality alongside throughput.',2,'Show the business impact and recovery tradeoffs. Preserve safety and first-pass quality while measuring accepted output.','Leadership can decide on resources and customer commitments using a defensible forecast.'),
        choice('Promise the original date and hide the unresolved shipment.',0,'Suppressing a known dependency deprives leaders of the chance to mitigate it.','The schedule miss becomes a surprise that the organization cannot plan around.'),
        choice('Report only racks installed per day.',1,'Installed quantity is useful but does not prove accepted capacity. Pair it with quality, rework, safety, and dependency status.','Throughput is visible, but usable capacity and remaining risk are unclear.')])]},
    {id:'label-mismatch', icon:'07', title:'The wrong end of the cable', area:'Mapping & configuration', duration:'4 decisions', intro:'During a deployment, the cable label, rack elevation, and switch-port record disagree. A technician suggests trusting whichever source is newest.', steps:[
      step('Control the uncertainty','What do you direct first?',[
        choice('Pause affected work, identify potentially impacted circuits, and reconcile the approved design with the actual installation and owners.',2,'A discrepancy can lead to the wrong cable being unplugged. Resolve identity before modifying anything.','Affected ports are isolated in the work plan, protecting neighboring production circuits.'),
        choice('Unplug the cable and see which device alarms.',0,'Using an outage to identify a circuit is unsafe and disruptive. Follow an authorized tracing and verification procedure.','The proposed identification method risks interrupting an unknown service.'),
        choice('Use the most recent spreadsheet without checking its approval.',1,'Recency alone is not authority. Verify the controlled source and actual installed state with the owner.','The newest file contains an unapproved edit, so the circuit remains unresolved.')]),
      step('Verify the complete path','How do you resolve the mapping?',[
        choice('Use authorized non-disruptive tracing and peer verification of both endpoints, device identities, and approved port assignments.',2,'Verify the whole path and record evidence. Use the site-approved method; do not assume cable color proves purpose.','The peer check identifies a swapped endpoint label while the actual connection matches the design.'),
        choice('Relabel only the visible end to make the spreadsheet match.',0,'Changing one end can conceal the discrepancy and mislead the next team. Labels and records must reflect verified reality.','The opposite endpoint still contradicts the record and creates a future maintenance risk.'),
        choice('Infer the path from cable color.',0,'Cable colors may support site conventions, but they are not sufficient evidence of endpoint identity.','Several same-color cables serve different circuits; identity remains unverified.')]),
      step('Control any change','The mapping is known. A configuration discrepancy is also found. What now?',[
        choice('Record the discrepancy, engage the network owner, and correct it through the approved change process with one variable at a time.',2,'Physical delivery and network configuration require aligned ownership. Keep the known baseline and define validation and rollback.','The network owner verifies the intended VLAN and applies the authorized correction.'),
        choice('Make the port a trunk carrying every VLAN to ensure connectivity.',0,'Opening broad VLAN access can violate segmentation and the approved design. Connectivity is not the only acceptance criterion.','The proposed shortcut creates a segmentation risk and must be rejected.'),
        choice('Leave it undocumented because the device seems to work.',0,'Unrecorded divergence causes future incidents and makes acceptance unreliable.','A latent configuration defect remains without an accountable owner.')]),
      step('Leave a reliable record','What completes this correction?',[
        choice('Validate service and intended segmentation, reconcile labels at both ends and controlled records, attach evidence, and notify the receiving owner.',2,'The next operator needs reliable identity and an accepted configuration, not merely a working link today.','The physical installation and controlled records agree, with peer-check evidence attached.'),
        choice('Update only your private notes.',0,'Private notes do not repair the operational source of truth or inform the teams that depend on it.','The next shift still sees conflicting records.'),
        choice('Fix all labels but omit the test evidence.',1,'Accurate labeling is necessary, but acceptance also needs evidence that the intended service and configuration are correct.','Identity is now reliable; the receiving owner still needs validation results.')])]},
    {id:'safety-deadline', icon:'08', title:'The deadline versus the lift', area:'Safety & team leadership', duration:'4 decisions', intro:'A heavy server must be installed before a customer milestone. The approved lift is unavailable, and an experienced technician proposes a manual lift that bypasses the site procedure.', steps:[
      step('Make the safety decision','What do you do?',[
        choice('Stop the unsafe lift, make the work area safe, and arrange the approved equipment and qualified personnel.',2,'People come first. A deadline does not authorize bypassing a safe handling procedure. Follow the equipment and site requirements.','The team stops before anyone is injured and secures the equipment.'),
        choice('Allow it because the technician has done it before.',0,'Experience does not replace the approved lifting method or eliminate the hazard.','The proposal exposes personnel and equipment to an avoidable lifting risk.'),
        choice('Ask the team to vote on whether the lift feels safe.',0,'Safety controls are not decided by a popularity vote. The manager must apply the approved procedure.','Pressure from the deadline prevents an objective assessment of the risk.')]),
      step('Recover useful work','How do you protect the schedule while the correct lift is sourced?',[
        choice('Resequence independent safe work, confirm the lift and staffing ETA, and reassess the critical path and milestone risk.',2,'Recover time through readiness and sequencing. Do not replace a safety gate with an improvised shortcut.','The team completes staging, labeling preparation, and documentation while logistics sources the approved lift.'),
        choice('Promise there will be no delay before checking equipment availability.',0,'An unsupported promise creates pressure to repeat the unsafe shortcut.','The team has a public deadline commitment with no verified safe execution path.'),
        choice('Send everyone home without checking available safe work.',1,'A stand-down may be required in some conditions, but first assess whether independent safe work can proceed under site controls.','The immediate risk is avoided; potentially useful critical-path work remains idle.')]),
      step('Coach and escalate','How do you address the technician and stakeholders?',[
        choice('Explain the hazard and required standard respectfully, acknowledge the stop-work action, and escalate the schedule risk with options and owners.',2,'Combine accountability with a speak-up culture. Stakeholders need a factual risk and a workable recovery plan.','The technician understands the requirement, and leadership helps secure the equipment without weakening the safety gate.'),
        choice('Publicly shame the technician to make an example.',0,'Humiliation discourages reporting and does not teach the right procedure. Coach directly and use the appropriate accountability process.','Other technicians become less willing to report near misses or question unsafe work.'),
        choice('Avoid discussing it so morale stays high.',0,'Ignoring an unsafe proposal leaves the expectation unclear and increases the chance of recurrence.','The team receives no clear guidance about future lifting decisions.')]),
      step('Finish with learning','The approved lift arrives and installation passes. What follows?',[
        choice('Complete acceptance, record the safety observation or near miss under site policy, and improve readiness checks for equipment and staffing.',2,'Capture system improvements: equipment availability, readiness gates, scheduling, and training. Do not treat an injury-free outcome as proof the shortcut was safe.','Future readiness reviews now verify lift availability before the installation is scheduled.'),
        choice('Omit the safety record because nobody was injured.',0,'Near misses and safety observations are leading indicators. Follow site reporting policy and learn before harm occurs.','The same resource gap can recur without a visible prevention action.'),
        choice('Record only the delay duration.',1,'Schedule impact matters, but the safety cause and corrective actions are essential to prevent recurrence.','The delay is measured; the reason and prevention mechanism remain missing.')])]}
  ];

  const q = (id, type, prompt, coaching) => ({id,type,prompt,coaching});
  const banks = {
    definition:[
      q('vlan','Definition','Explain a VLAN, an access port, and a trunk port to a new technician.','A VLAN separates Layer 2 broadcast domains. An access port normally belongs to one data VLAN; a trunk carries multiple allowed VLANs, typically with 802.1Q tags. Explain the approved port design and why a wrong VLAN can leave link up but service unreachable. Avoid changing production configuration without its owner.'),
      q('incident-problem','Definition','How do incident management, problem management, and change management differ?','Incident management restores service and controls impact. Problem management investigates causes and recurrence. Change management evaluates and authorizes risk before modifications. Explain how an incident may use the approved emergency-change path, then feed a later problem review.'),
      q('rack-handoff','Definition','What makes a rack ready for handoff?','Use agreed acceptance criteria: safe installation, correct rack elevation and inventory, approved A/B power, cable routing and labels, certified links where required, approved configuration, end-to-end checks, documented exceptions, and an accountable receiving owner. Physical installation alone is not accepted capacity.'),
      q('optical-tools','Definition','Compare a visual fault locator, optical power meter, and OTDR.','A VFL helps identify continuity and some visible faults. A power meter measures received optical power; a calibrated source and meter measure insertion loss. An OTDR helps locate events along a fiber. Correct setup and the acceptance plan determine required tests. Never look into a fiber end.'),
      q('mop','Definition','What belongs in a useful method of procedure and rollback plan?','Include scope, prerequisites, risk/impact, roles, authorization, equipment and circuit identities, safe ordered steps, checkpoints, stop/rollback triggers, executable rollback steps, time estimates, validation, and communication. The plan must fit the permitted window and be usable by the executing team.'),
      q('layers','Definition','Walk through Layers 1–4 using a server-to-service connection.','Layer 1: power, cable, optic, link signal. Layer 2: Ethernet frames, MAC addresses, VLANs, switching. Layer 3: IP, subnet, gateway, routing. Layer 4: TCP/UDP and ports. A green link LED confirms neither IP reachability nor application health.'),
      q('capacity','Definition','What does capacity readiness mean beyond counting empty rack units?','Include space, power, cooling, network ports and bandwidth, hardware, optics/cables, skilled labor, supplier lead time, approvals, and validated delivery dates. Name dependency owners and escalation thresholds; track accepted usable capacity against demand.'),
      q('firstpass','Definition','Define first-pass yield and explain what you would measure alongside it.','First-pass yield is the proportion that passes a defined acceptance gate on its first attempt. State the denominator and time window. Pair it with throughput, defects/rework, backlog age, delivery milestones, safety and near-miss reporting, and skill coverage. Do not reward unsafe shortcuts or penalize reporting.'),
      q('tcp-dns','Definition','Compare DNS, TCP, and a default gateway in one request to a remote service.','DNS resolves a name to records such as an address. The host uses its prefix/routing table to choose a route, often through a default gateway for off-subnet traffic. TCP establishes a connection between ports with reliable ordered delivery. Name resolution, IP reachability, and transport/application success are separate checks.'),
      q('linux-commands','Definition','What can ip addr, ip route, ss, and journalctl tell you on a Linux host?','ip addr shows interface addresses and state; ip route shows routing decisions; ss shows sockets and listening services; journalctl shows systemd journal logs where available. Begin with permitted read-only inspection and relevant timestamps. Command availability, privileges, and logging vary by distribution; do not assume a command changes or proves service health.')
    ],
    troubleshooting:[
      q('new-server','Troubleshooting','A server powers on but has no network link. Lead the investigation through handoff.','State safety, impact, scope, and recent changes. Verify the approved mapping and inspect power/link state, cable seating, labels, optics compatibility and fiber condition safely. Isolate one variable at a time with approved known-good parts. Involve the network owner for speed/VLAN/addressing. Validate service, document evidence, and communicate acceptance.'),
      q('gateway','Troubleshooting','Link is up, but a Linux server cannot reach its default gateway. What do you inspect and who owns the changes?','Scope the fault and recent changes. Read ip addr and ip route, confirm prefix and expected gateway, check neighbor state with ip neigh, and coordinate VLAN/port checks with networking. Ping is one signal and may be filtered. Check errors and approved logs. Avoid blind address, route, or firewall changes; validate the agreed service after an authorized correction.'),
      q('dns','Troubleshooting','A Linux host reaches a service by IP but fails using its hostname. How do you narrow the problem?','Check the exact name, errors, and scope. Use approved DNS checks such as getent hosts, resolvectl where available, or dig if installed; inspect resolver configuration and name responses. An application can behave differently with IP versus hostname because of TLS or virtual hosting, so do not overclaim. Coordinate a narrow change, validate name-based service, and record evidence.'),
      q('flaps','Troubleshooting','A fiber uplink works intermittently after a cable-routing change. What is your plan?','Protect service and define authorized testing. Check time correlation, error counters, optical readings, bend/strain, compatibility, and connections with approved inspection-cleaning procedures. Never view a fiber directly. Use required loss tests and OTDR when useful. Change one variable at a time; monitor stability, validate services, and save circuit-specific evidence.'),
      q('many-servers','Troubleshooting','Six servers in the same rack fail together. What changes in your diagnostic approach?','Look for common dependencies: ToR switch, uplinks, power, shared configuration, and recent work. Establish an incident lead, scope and communication, freeze unrelated work, preserve logs, and delegate clear tasks. Do not independently reboot every server. Use authorized recovery and prove every affected service and redundancy are healthy.'),
      q('disk-full','Troubleshooting','A Linux deployment host reports “No space left on device.” What read-only checks help?','Check df -h for filesystem space and df -i for inode exhaustion; inspect the relevant mount and targeted disk usage with permitted du commands. Logs, deleted-open files, quotas, and permissions may require owner investigation. Do not delete files blindly or run broad disruptive scans. Coordinate retention-safe cleanup or capacity changes with rollback/backup considerations, then validate the affected workflow.'),
      q('failed-cert','Troubleshooting','A newly installed copper link fails certification. The vendor wants to waive the test to hit the date.','Block affected acceptance. Verify the cable identity, test standard/limit, tester setup/calibration and saved result; inspect termination, length, routing, damage, and installation requirements. Use qualified staff to correct the isolated fault and retest. Update the forecast honestly. Never turn an unverified link into accepted capacity by omitting the quality gate.'),
      q('mismatch','Troubleshooting','Physical labels and the port-mapping document disagree on a live connection. What do you do?','Pause affected work and protect unknown services. Reconcile the controlled design with actual endpoints using authorized tracing and a peer check. Include the service and network owners, document the discrepancy, and correct through change control if needed. Validate service and update both endpoint labels and the operational source of truth.')
    ],
    management:[
      q('vendor','Management','Your vendor reports 90% completion but only half the racks meet acceptance. How do you recover?','Use a joint evidence-based walkdown and the agreed definition of done. Reconcile accepted output, find critical dependencies, and build a recovery plan with owners, dates, resources, quality gates, and escalation triggers. Publish an honest forecast. Measure accepted throughput and first-pass yield rather than reported effort alone.'),
      q('unsafe-deadline','Management','Stopping an unsafe lift threatens a critical milestone. What do you do and how do you explain it?','Stop unsafe work and secure the area. Obtain the approved equipment and qualified staff. Resequence safe independent work and update the critical path. Escalate the deadline risk with options and owners. Coach respectfully, follow near-miss reporting policy, and improve readiness checks. People and safety remain the first priority.'),
      q('expert','Management','An experienced technician challenges your technical decision in front of the team. How do you lead?','Invite evidence and understand the risk without making it a contest. Recheck the design and involve the accountable expert when needed. Change your decision if evidence warrants it; state the final rationale and ownership. Address disrespect separately if necessary. Combine humility with clear safety and execution standards.'),
      q('coaching','Management','A technician repeatedly makes cabling-label errors. How do you improve performance fairly?','Confirm specific examples and the standard; observe the process and distinguish skill, unclear instructions, workload, and tool issues. Coach privately, provide practice/peer checks, set measurable expectations and follow-up dates, and monitor defect/rework trends. Reinforce improvement and use the appropriate accountability process if gaps persist.'),
      q('late','Management','A delivery is two weeks behind schedule. What do you inspect before adding overtime?','Rebuild the evidence-based plan: accepted output, critical path, materials, labor skills, approvals, testing resources, rework, and dependencies. Prioritize constraints and resequence ready work. Assess fatigue and quality risks of overtime. Assign a recovery owner and communicate a forecast with assumptions and decisions needed.'),
      q('quality-speed','Management','Throughput rises while first-pass yield falls. What changes do you make?','Check consistent definitions, denominators, mix, and trends. Separate installed work from accepted output; quantify rework and bottlenecks. Observe the process, remove incentives for shortcuts, improve readiness/standard work/training, and track safety, quality, and throughput together. Test the improvement and verify sustained results.'),
      q('handoff','Management','How would you make a night-shift handoff reliable during overlapping deployments?','Use a consistent handoff covering service state, approved work, completed/remaining steps, exact circuit and asset identities, risks, open changes, incident status, blockers, owners, and escalation paths. Require receiving acknowledgment and verify critical records. Plan coverage and fatigue controls rather than relying on one expert.'),
      q('first90','Management','What would your first 30, 60, and 90 days as an Infrastructure Delivery Manager look like?','First understand people, safety rules, service boundaries, delivery workflow, stakeholders, and baseline metrics. Then address evidence-backed constraints and clarify ownership/standards. Finally evaluate improvements, build skill coverage and capacity plans, and establish a durable review cadence. Avoid promising arbitrary gains before understanding the baseline.')
    ]
  };
  const starPrompts = [
    'Tell me about the most difficult technical problem you solved.',
    'Tell me about a technical project you delivered under a fixed deadline.',
    'Tell me about a time you found a problem others had missed.',
    'Tell me about a time you improved a technical process.',
    'Tell me about a decision you made without enough information.',
    'Tell me about a time you made the wrong technical decision.',
    'Tell me about a time you prevented a safety or quality problem.',
    'Tell me about a time you learned unfamiliar technology quickly.',
    'Tell me about a time you disagreed with a technical expert.',
    'Tell me about a time a vendor failed to meet expectations.',
    'Tell me about a time you used measurements to improve performance.',
    'Tell me about a time you managed several urgent technical priorities.',
    'Tell me about a time you coached someone through a technical problem.',
    'Tell me about a time you escalated a serious risk.',
    'Tell me about a project that failed or missed a commitment.',
    'Tell me about a time you earned the trust of a more experienced team.',
    'Tell me about a time you improved a shift handoff or reduced reliance on one expert.',
    'Tell me about a time you took responsibility for a customer-impacting mistake.'
  ];
  banks.star = starPrompts.map((prompt,i)=>q('star-'+i,'STAR',prompt,'Use a real experience, including relevant AV/rental work if that is your background. Briefly set the situation and your task; spend most time on your own actions, tradeoffs, and coordination. Finish with the actual result, evidence or honestly qualified estimates, and what changed afterward. Do not invent data-center experience, team sizes, metrics, or outcomes. Explain which skills transfer and which technical details you would verify in the new environment.'));
  banks.followup = [
    q('personal','Follow-up','What did you personally do, and what did other people own?','Make your contribution unmistakable without taking credit for the team’s work. Name decisions you made, actions you executed, delegation, and how you verified completion.'),
    q('scale','Follow-up','How many people or devices were involved? What was the actual scope?','Use truthful specifics or a clearly labeled approximation. State your role, timeline, affected customers or systems, and the limits of your responsibility. Never invent scale to strengthen the story.'),
    q('alternatives','Follow-up','What other options did you consider, and why was your choice defensible?','Compare realistic alternatives using safety, impact, time, cost, reversibility, and evidence. Explain the decision threshold and what new evidence would have changed your mind.'),
    q('disagreed','Follow-up','Who disagreed with your approach, and how did you resolve that disagreement?','Describe the actual concern respectfully. Explain how you sought evidence, listened, used the appropriate decision owner, and aligned execution. If no one disagreed, say so; do not manufacture conflict.'),
    q('measure','Follow-up','What measurements did you use, and how do you know the result was real?','Define the baseline, measure, denominator, and time period where applicable. Distinguish observed results from estimates. Explain your validation and any limitations in the evidence.'),
    q('different','Follow-up','What would you do differently if you faced the same situation tomorrow?','Identify a specific improvement grounded in what happened. Explain an earlier check, clearer ownership, safer decision, or stronger verification—not a generic promise to communicate better.'),
    q('recur','Follow-up','How did you prevent recurrence, and how did you check that the fix lasted?','Give an owned corrective action, due date, changed process or technical control, and a follow-up measure. If you did not check long-term effectiveness, be honest and explain how you would do it now.'),
    q('rollback-probe','Follow-up','What would have made you stop or reverse your decision?','Name observable stop/rollback triggers, the decision owner, a usable recovery path, and time limits. Explain what risk you would never accept merely to preserve the schedule.'),
    q('bad-news','Follow-up','How did you communicate bad news, and what decision did you need from leadership?','State impact and facts early, show options and their tradeoffs, recommend an action, assign ownership, and set the next update. Do not disguise uncertainty as certainty.'),
    q('proof','Follow-up','If I challenged your claim that the work was complete, what evidence would you show me?','Point to accepted deliverables, agreed test results, a verified metric, customer or receiving-owner acceptance, and accurate records. Distinguish activity performed from outcomes actually achieved.')
  ];
  const rubric = [
    {id:'technical',name:'Technical accuracy',levels:['Incorrect or unsupported','Partly correct','Accurate and relevant']},
    {id:'safety',name:'Safety & change control',levels:['Missing where relevant','Mentioned','Drives the decision']},
    {id:'management',name:'Management',levels:['No ownership','Some coordination','Owners and escalation clear']},
    {id:'verification',name:'Verification',levels:['Assumes success','Basic check','Acceptance evidence and records']},
    {id:'communication',name:'Communication',levels:['Confusing','Understandable','Concise and structured']}
  ];
  const pick = a => a[Math.floor(Math.random()*a.length)];
  const shuffled = a => { const result=[...a];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result; };
  function readStorage(key) { try { return JSON.parse(localStorage.getItem(key)||'null'); } catch (_) { return null; } }
  function writeStorage(key,value) { try { localStorage.setItem(key,JSON.stringify(value)); return true; } catch (_) { return false; } }

  function mount(container, options) {
    options = options || {};
    let cleanup = ()=>{};
    if (options.mode === 'interview') cleanup = mountInterview(container,options);
    else cleanup = mountIncidents(container,options);
    return cleanup;
  }
  function mountIncidents(container, options) {
    let current=null, index=0, selected=null, history=[], result=false;
    const rawBest=readStorage('dc-lab:incident-best:v1');
    let best = rawBest && typeof rawBest==='object' && !Array.isArray(rawBest) ? rawBest : {};
    const freshMission = id => {const original=incidents.find(x=>x.id===id);return original?{...original,steps:original.steps.map(s=>({...s,choices:shuffled(s.choices)}))}:null;};
    const score=()=>history.reduce((sum,item)=>sum+item.score,0);
    const max=()=>current.steps.length*2;
    function render(focus) {
      if(!current) {
        container.innerHTML='<section class="scenario-room"><div class="scenario-intro"><p class="scenario-eyebrow">DECISION SIMULATOR</p><h2>Lead the response.</h2><p>Eight operational missions. Your choices change the next handoff, the risk, and the evidence you inherit. Choose a response, study the consequence, then make the next call.</p></div><div class="scenario-priority"><span>YOUR PRIORITY ORDER</span><strong>People <b>→</b> Facility & equipment <b>→</b> Service <b>→</b> Schedule</strong></div><div class="scenario-grid">'+incidents.map(item=>'<button class="scenario-card" data-action="start" data-id="'+item.id+'"><span class="scenario-card-top"><span class="scenario-number">'+item.icon+'</span><span class="scenario-chip">'+item.duration+'</span></span><span class="scenario-card-title">'+esc(item.title)+'</span><span class="scenario-card-area">'+esc(item.area)+'</span><span class="scenario-card-copy">'+esc(item.intro)+'</span><span class="scenario-card-footer">'+(typeof best[item.id]==='number'?'Personal best '+best[item.id]+'/'+(item.steps.length*2):'Start mission')+' <span aria-hidden="true">↗</span></span></button>').join('')+'</div><p class="scenario-footnote">These are practice scenarios, not operating procedures. Follow your site’s approved methods, training, and decision authority.</p></section>';
      } else if(result) {
        const total=score(), percentage=Math.round(total/max()*100);
        container.innerHTML='<section class="scenario-room scenario-result"><p class="scenario-eyebrow">MISSION DEBRIEF · '+esc(current.area)+'</p><h2>'+esc(current.title)+'</h2><div class="scenario-score"><strong>'+total+'<small>/'+max()+'</small></strong><div><span>'+ (percentage===100?'Ready for the handoff':percentage>=63?'A solid foundation':'Review the decision sequence')+'</span><p>'+ (percentage===100?'You protected people, controlled the work, and closed with evidence.':'Use the debrief to turn each missed decision into a repeatable habit.')+'</p></div></div><div class="scenario-debrief">'+history.map((answer,i)=>'<article><div class="scenario-debrief-head"><span>'+String(i+1).padStart(2,'0')+' · '+esc(current.steps[i].title)+'</span><strong>'+answer.score+'/2</strong></div><p class="scenario-chosen">'+esc(answer.text)+'</p><p>'+esc(answer.feedback)+'</p>'+(answer.score<2?'<p class="scenario-better"><strong>Stronger move:</strong> '+esc(current.steps[i].choices.find(c=>c.score===2).text)+'</p>':'')+'</article>').join('')+'</div><div class="scenario-actions"><button class="scenario-primary" data-action="replay">Replay mission</button><button class="scenario-secondary" data-action="menu">Choose another mission</button></div><p class="scenario-footnote">Practice score from fixed decision rules. No real interview outcome is predicted.</p></section>';
      } else {
        const s=current.steps[index];
        container.innerHTML='<section class="scenario-room"><div class="scenario-topbar"><button class="scenario-back" data-action="menu">← All missions</button><span class="scenario-chip">Decision '+(index+1)+' of '+current.steps.length+'</span></div><div class="scenario-steps" aria-label="Mission progress">'+current.steps.map((x,i)=>'<span class="'+(i<index?'is-done':i===index?'is-current':'')+'" '+(i===index?'aria-current="step"':'')+'><b>'+String(i+1).padStart(2,'0')+'</b>'+esc(x.title)+'</span>').join('')+'</div><div class="scenario-mission-heading"><p class="scenario-eyebrow">'+esc(current.area)+'</p><h2>'+esc(current.title)+'</h2><p>'+esc(current.intro)+'</p></div>'+(index?'<div class="scenario-consequence"><span>STATE YOU INHERITED</span><p>'+esc(history[index-1].consequence)+'</p></div>':'')+'<div class="scenario-question"><h3>'+esc(s.title)+'</h3><p>'+esc(s.prompt)+'</p><div class="scenario-choices">'+s.choices.map((c,i)=>'<button class="scenario-choice '+(selected===i?'is-selected '+(c.score===2?'is-good':c.score===1?'is-partial':'is-risky'):'')+'" data-action="choose" data-choice="'+i+'" '+(selected!==null?'disabled':'')+'><span class="scenario-letter">'+String.fromCharCode(65+i)+'</span><span>'+esc(c.text)+'</span>'+(selected===i?'<strong>'+c.score+'/2</strong>':'')+'</button>').join('')+'</div></div>'+(selected!==null?'<div class="scenario-feedback" role="status"><span class="scenario-feedback-label">'+(s.choices[selected].score===2?'Sound decision':s.choices[selected].score===1?'Useful start, missing a control':'Risk introduced')+'</span><p>'+esc(s.choices[selected].feedback)+'</p><div class="scenario-impact"><strong>Consequence</strong><p>'+esc(s.choices[selected].consequence)+'</p></div><button class="scenario-primary" data-action="next">'+(index===current.steps.length-1?'View mission debrief':'Continue response')+' <span aria-hidden="true">→</span></button></div>':'<p class="scenario-hint">Choose the best next action. Each decision is scored from 0 to 2.</p>')+'</section>';
      }
      if(focus){ const el=container.querySelector(focus); if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true});} }
    }
    function action(event){
      const button=event.target.closest('button[data-action]'); if(!button||!container.contains(button))return;
      const type=button.dataset.action;
      if(type==='start'){ current=freshMission(button.dataset.id);index=0;selected=null;history=[];result=false;render('h2'); }
      if(type==='menu'){current=null;render('h2');}
      if(type==='replay'){current=freshMission(current.id);index=0;selected=null;history=[];result=false;render('h2');}
      if(type==='choose'&&selected===null){selected=Number(button.dataset.choice);render('.scenario-feedback');}
      if(type==='next'&&selected!==null){
        history.push(current.steps[index].choices[selected]);
        if(index===current.steps.length-1){
          result=true;best[current.id]=Math.max(Number(best[current.id])||0,score());writeStorage('dc-lab:incident-best:v1',best);
          if(typeof options.onComplete==='function')options.onComplete({id:'incident:'+current.id,score:score(),max:max()});
          render('h2');
        }else{index++;selected=null;render('.scenario-consequence');}
      }
    }
    container.addEventListener('click',action);render();
    return ()=>container.removeEventListener('click',action);
  }

  function mountInterview(container,options){
    const storageKey='dc-lab:interview-round:v1';
    let round=readStorage(storageKey), elapsed=120, ticking=false, timer=null, saveTimer=null, saved=true, showLibrary=false, disposed=false;
    const known=new Map(Object.values(banks).flat().map(item=>[item.id,item]));
    function validRound(r){return r&&Array.isArray(r.questions)&&r.questions.length===6&&r.questions.every(id=>known.has(id))&&Array.isArray(r.answers)&&r.answers.length===6&&r.answers.every(a=>a&&typeof a.text==='string'&&a.scores&&typeof a.scores==='object'&&rubric.every(d=>a.scores[d.id]===null||[0,1,2].includes(a.scores[d.id])))&&Number.isInteger(r.index)&&r.index>=0&&r.index<6;}
    if(!validRound(round))round=null;
    function persist(){if(disposed)return;saved=writeStorage(storageKey,round);const status=container.querySelector('.interview-save-status');if(status)status.textContent=saved?'Draft saved in this browser':'Storage unavailable — keep a copy of your answer before leaving';}
    function stopTimer(){ticking=false;if(timer){clearInterval(timer);timer=null;}}
    function resetTimer(){stopTimer();elapsed=120;}
    function newRound(starId){
      const followups=shuffled(banks.followup).slice(0,2);
      round={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),index:0,completed:false,questions:[pick(banks.definition),pick(banks.troubleshooting),pick(banks.management),starId?known.get(starId):pick(banks.star),...followups].map(x=>x.id),answers:Array.from({length:6},()=>({text:'',revealed:false,scores:Object.fromEntries(rubric.map(d=>[d.id,null]))}))};
      showLibrary=false;resetTimer();persist();render('h2');
    }
    const total=()=>round.answers.reduce((sum,a)=>sum+rubric.reduce((t,d)=>t+(Number(a.scores[d.id])||0),0),0);
    const assessed=a=>rubric.every(d=>a.scores[d.id]!==null);
    const questionScore=a=>rubric.reduce((t,d)=>t+(Number(a.scores[d.id])||0),0);
    function timerMarkup(){return '<div class="interview-timer"><div><span class="interview-timer-caption">OPTIONAL ANSWER TIMER</span><strong id="interview-time" aria-label="Time remaining">'+Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0')+'</strong></div><button class="scenario-secondary" data-action="timer">'+(ticking?'Pause timer':elapsed===0?'Restart 2 minutes':elapsed<120?'Resume timer':'Start 2 minutes')+'</button><button class="interview-reset" data-action="timer-reset" aria-label="Reset timer to two minutes">Reset</button><span class="interview-timer-status" role="status">'+(elapsed===0?'Time is up. Finish your thought; there is no penalty.':'')+'</span></div>';}
    function focusOn(selector){const el=container.querySelector(selector);if(el){if(!/^(BUTTON|INPUT|TEXTAREA|SELECT|A)$/.test(el.tagName))el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}}
    function render(focus){
      if(showLibrary){
        container.innerHTML='<section class="interview-room"><div class="scenario-topbar"><button class="scenario-back" data-action="back">← Interview room</button><span class="scenario-chip">18 story prompts</span></div><p class="scenario-eyebrow">BUILD YOUR REAL STORY BANK</p><h2>Experiences you can defend.</h2><p class="interview-lead">Use a specific experience you actually had. AV, rental, logistics, installation, and people-management stories can demonstrate transferable skills. Be clear about the setting and your personal contribution.</p><div class="interview-truth"><strong>Specific beats inflated.</strong><p>Use real numbers, or call an estimate an estimate. If you have no direct example, say so and explain a relevant experience or your approach. Never invent data-center experience.</p></div>'+(round?'<p class="scenario-footnote">Choosing a prompt starts a new round and replaces your current draft. Return to the interview room and copy your notes first if you want to keep them.</p>':'')+'<div class="interview-library">'+banks.star.map((item,i)=>'<button data-action="star" data-id="'+item.id+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(item.prompt)+'</strong><small>Use in a new six-question round →</small></button>').join('')+'</div></section>';
      }else if(!round){
        container.innerHTML='<section class="interview-room"><p class="scenario-eyebrow">MOCK INTERVIEW</p><h2>Think clearly. Answer with evidence.</h2><p class="interview-lead">A six-question practice round mirrors the mix in your study notes: technical fundamentals, diagnosis, delivery leadership, a real STAR story, and two tough follow-ups on your answers.</p><div class="interview-round-map">'+['01 · Definition','02 · Troubleshooting','03 · Management','04 · STAR story','05 · Follow-up','06 · Follow-up'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="interview-truth"><strong>You assess your own answer.</strong><p>Write or rehearse aloud, reveal the coaching, then rate five dimensions from 0–2. This tool does not use AI to grade answers. The optional two-minute timer never locks your answer.</p></div><div class="scenario-actions"><button class="scenario-primary" data-action="new">Start interview round →</button><button class="scenario-secondary" data-action="library">Explore 18 STAR prompts</button></div><p class="scenario-footnote">Typed drafts are stored only in this browser when storage is available. They are not sent to a grading service. Refreshing preserves the current round; starting a new round replaces it. Avoid confidential employer or customer details.</p></section>';
      }else if(round.completed){
        const weak=rubric.map(d=>({name:d.name,value:round.answers.reduce((sum,a)=>sum+(Number(a.scores[d.id])||0),0)})).sort((a,b)=>a.value-b.value);
        container.innerHTML='<section class="interview-room"><p class="scenario-eyebrow">ROUND COMPLETE · SELF-ASSESSMENT</p><h2>Turn reflection into your next repetition.</h2><div class="scenario-score"><strong>'+total()+'<small>/60</small></strong><div><span>Your own rubric score</span><p>This reflects your ratings, not an automated assessment or an interview prediction.</p></div></div><div class="interview-dimension-summary">'+weak.map(d=>'<div><span>'+esc(d.name)+'</span><strong>'+d.value+'/12</strong><progress value="'+d.value+'" max="12" aria-label="'+esc(d.name)+' '+d.value+' out of 12"></progress></div>').join('')+'</div><p class="interview-next-step"><strong>Next focus:</strong> Review '+esc(weak[0].name.toLowerCase())+' and '+esc(weak[1].name.toLowerCase())+' in your next round. Ask someone you trust to challenge your reasoning and evidence.</p><div class="interview-results">'+round.questions.map((id,i)=>'<button data-action="review" data-index="'+i+'"><span>'+String(i+1).padStart(2,'0')+' · '+esc(known.get(id).type)+'</span><strong>'+esc(known.get(id).prompt)+'</strong><b>'+questionScore(round.answers[i])+'/10 →</b></button>').join('')+'</div><div class="scenario-actions"><button class="scenario-primary" data-action="new">Start a new round</button><button class="scenario-secondary" data-action="copy">Copy answers and ratings</button><button class="scenario-secondary" data-action="library">STAR prompt library</button></div><p class="interview-copy-status" role="status"></p><p class="scenario-footnote">Copy your answers before starting a new round if you want to keep them.</p></section>';
      }else{
        const i=round.index,item=known.get(round.questions[i]),answer=round.answers[i];
        container.innerHTML='<section class="interview-room"><div class="scenario-topbar"><span class="scenario-chip">'+esc(item.type)+' · '+(i+1)+' of 6</span><button class="scenario-back" data-action="library">STAR prompt library ↗</button></div><nav class="interview-question-nav" aria-label="Interview questions">'+round.questions.map((id,n)=>'<button data-action="goto" data-index="'+n+'" class="'+(n===i?'is-current':assessed(round.answers[n])?'is-scored':'')+'" '+(n===i?'aria-current="step"':'')+'><span>'+String(n+1).padStart(2,'0')+'</span>'+esc(known.get(id).type)+(assessed(round.answers[n])?'<span class="interview-nav-check" aria-label="Assessed">✓</span>':'')+'</button>').join('')+'</nav><p class="scenario-eyebrow">'+(item.type==='Follow-up'?'DEFEND YOUR PREVIOUS ANSWER':'PRACTICE OUT LOUD, THEN CAPTURE YOUR THINKING')+'</p><h2>'+esc(item.prompt)+'</h2>'+(item.type==='Follow-up'?'<p class="interview-followup-context">Apply this follow-up to your STAR story: <strong>'+esc(known.get(round.questions[3]).prompt)+'</strong> You may also use another answer from this round.</p>':'')+timerMarkup()+(item.type==='STAR'?'<details class="interview-scaffold"><summary>Open the STAR answer scaffold</summary><div><p><strong>Situation:</strong> Where were you, what was at stake, and what constraints mattered?</p><p><strong>Task:</strong> What were you personally accountable for?</p><p><strong>Action:</strong> What did you do, why, with whom, and how did you control risk?</p><p><strong>Result:</strong> What actually changed, how did you verify it, and what did you learn?</p><p class="interview-scaffold-note">Keep context brief. Spend most of your answer on your actions. Use real evidence; label estimates honestly.</p></div></details>':'')+'<div class="interview-answer"><label for="interview-answer-text">Your answer or speaking notes</label><textarea id="interview-answer-text" rows="7" placeholder="State the situation, make the decision, explain why, and show how you would verify the result…">'+esc(answer.text)+'</textarea><div class="interview-answer-meta"><span class="interview-save-status" role="status">'+(saved?'Draft saved in this browser':'Storage unavailable — keep a copy before leaving')+'</span><span id="interview-word-count">'+countWords(answer.text)+' words</span></div></div><button class="scenario-secondary interview-reveal" data-action="reveal" aria-expanded="'+Boolean(answer.revealed)+'">'+(answer.revealed?'Hide answer coaching':'Reveal coaching & self-assessment')+'</button>'+(answer.revealed?'<section class="interview-coaching"><p class="scenario-eyebrow">COACHING · COMPARE YOUR REASONING</p><p>'+esc(item.coaching)+'</p><div class="interview-rubric-intro"><h3>Rate your answer honestly</h3><p>These are your own ratings. Apply each dimension proportionately to the question; do not force an unrelated safety or management example into a short definition.</p></div><div class="interview-rubric">'+rubric.map(d=>'<fieldset><legend>'+esc(d.name)+'</legend><div>'+d.levels.map((label,n)=>'<label class="'+(answer.scores[d.id]===n?'is-selected':'')+'"><input type="radio" name="rubric-'+d.id+'" data-rubric="'+d.id+'" value="'+n+'" '+(answer.scores[d.id]===n?'checked':'')+'><span><b>'+n+'</b>'+esc(label)+'</span></label>').join('')+'</div></fieldset>').join('')+'</div><p class="interview-current-score" role="status">'+(assessed(answer)?'Your rating: '+questionScore(answer)+'/10':'Choose a rating for each of the five dimensions.')+'</p></section>':'')+'<div class="scenario-actions interview-bottom-actions"><button class="scenario-secondary" data-action="previous" '+(i===0?'disabled':'')+'>← Previous</button>'+(i<5?'<button class="scenario-primary" data-action="next">Next question →</button>':'<button class="scenario-primary" data-action="finish">Finish self-assessment →</button>')+'<button class="interview-reset" data-action="copy">Copy round notes</button></div><p class="interview-copy-status" role="status"></p><p class="interview-validation" role="status"></p><p class="scenario-footnote">Coaching is a practice framework, not an official interview answer key. Follow approved site procedures in real operations.</p></section>';
      }
      if(focus)focusOn(focus);
    }
    function countWords(text){return text.trim()?text.trim().split(/\s+/).length:0;}
    function move(index){resetTimer();round.index=index;persist();render('h2');}
    function updateTimer(){
      const time=container.querySelector('#interview-time');if(time)time.textContent=Math.floor(elapsed/60)+':'+String(elapsed%60).padStart(2,'0');
      const button=container.querySelector('[data-action="timer"]');if(button)button.textContent=ticking?'Pause timer':elapsed===0?'Restart 2 minutes':elapsed<120?'Resume timer':'Start 2 minutes';
      const status=container.querySelector('.interview-timer-status');if(status)status.textContent=elapsed===0?'Time is up. Finish your thought; there is no penalty.':'';
    }
    async function copyRound(){
      const copy=round.questions.map((id,i)=>{const a=round.answers[i];return (i+1)+'. '+known.get(id).type+': '+known.get(id).prompt+'\n\n'+(a.text||'[Practiced aloud — no written notes]')+'\n\nSelf-assessment: '+rubric.map(d=>d.name+': '+(a.scores[d.id]===null?'unrated':a.scores[d.id]+'/2')).join('; ');}).join('\n\n————————————\n\n');
      let ok=false;try{await navigator.clipboard.writeText(copy);ok=true;}catch(_){}
      if(disposed)return;
      const status=container.querySelector('.interview-copy-status');
      if(ok){if(status)status.textContent='Round notes and self-assessment copied.';}
      else if(status){status.innerHTML='<label for="interview-copy-fallback">Clipboard access unavailable. Select and copy your notes here:</label><textarea id="interview-copy-fallback" rows="6" readonly>'+esc(copy)+'</textarea>';const el=status.querySelector('textarea');el.focus();el.select();}
    }
    function action(event){
      const button=event.target.closest('button[data-action]');if(!button||!container.contains(button))return;
      const type=button.dataset.action;
      if(type==='new')newRound();
      if(type==='library'){stopTimer();showLibrary=true;render('h2');}
      if(type==='back'){showLibrary=false;render('h2');}
      if(type==='star'){newRound(button.dataset.id);round.index=3;persist();render('h2');}
      if(type==='goto')move(Number(button.dataset.index));
      if(type==='review'){round.completed=false;round.index=Number(button.dataset.index);resetTimer();persist();render('h2');}
      if(type==='previous'&&round.index>0)move(round.index-1);
      if(type==='next'&&round.index<5)move(round.index+1);
      if(type==='reveal'){round.answers[round.index].revealed=!round.answers[round.index].revealed;persist();render(round.answers[round.index].revealed?'.interview-coaching':'.interview-reveal');}
      if(type==='timer'){
        if(ticking)stopTimer();else{if(elapsed===0)elapsed=120;ticking=true;timer=setInterval(()=>{elapsed=Math.max(0,elapsed-1);if(elapsed===0)stopTimer();updateTimer();},1000);}updateTimer();
      }
      if(type==='timer-reset'){resetTimer();updateTimer();}
      if(type==='copy')copyRound();
      if(type==='finish'){
        const missing=round.answers.findIndex(a=>!assessed(a));
        if(missing!==-1){round.index=missing;round.answers[missing].revealed=true;resetTimer();persist();render('.interview-rubric-intro');const status=container.querySelector('.interview-validation');status.textContent='Complete all five self-ratings for question '+(missing+1)+' before finishing. Written notes are optional if you practiced aloud.';}
        else{stopTimer();round.completed=true;persist();if(typeof options.onComplete==='function')options.onComplete({id:'interview:'+round.id,score:total(),max:60});render('h2');}
      }
    }
    function input(event){
      if(event.target.id==='interview-answer-text'){
        round.answers[round.index].text=event.target.value;
        const count=container.querySelector('#interview-word-count');if(count)count.textContent=countWords(event.target.value)+' words';
        const status=container.querySelector('.interview-save-status');if(status)status.textContent='Saving draft…';
        if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(persist,250);
      }
    }
    function change(event){
      const id=event.target.dataset.rubric;if(!id||!rubric.some(d=>d.id===id))return;
      round.answers[round.index].scores[id]=Number(event.target.value);persist();
      const field=event.target.closest('fieldset');field.querySelectorAll('label').forEach(label=>label.classList.toggle('is-selected',label.querySelector('input').checked));
      const score=container.querySelector('.interview-current-score');score.textContent=assessed(round.answers[round.index])?'Your rating: '+questionScore(round.answers[round.index])+'/10':'Choose a rating for each of the five dimensions.';
      if(assessed(round.answers[round.index])){const nav=container.querySelectorAll('.interview-question-nav button')[round.index];if(nav&&!nav.querySelector('.interview-nav-check'))nav.insertAdjacentHTML('beforeend','<span class="interview-nav-check" aria-label="Assessed">✓</span>');}
    }
    function flush(){if(round)persist();}
    container.addEventListener('click',action);container.addEventListener('input',input);container.addEventListener('change',change);window.addEventListener('pagehide',flush);render();
    return ()=>{stopTimer();if(saveTimer)clearTimeout(saveTimer);if(round)persist();disposed=true;container.removeEventListener('click',action);container.removeEventListener('input',input);container.removeEventListener('change',change);window.removeEventListener('pagehide',flush);};
  }
  window.ScenarioRoom={mount};
})();
